-- Additive Runner authority and immutable automation histories. No old facts or counters change.
CREATE TABLE automation_runners (owner_id TEXT NOT NULL REFERENCES flora_deployment(owner_id), id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,id,version), CHECK(stored_bytes=length(CAST(json_array(owner_id,id,version,data) AS BLOB)))) STRICT;
CREATE TABLE automation_jobs (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, id TEXT NOT NULL, request_key TEXT NOT NULL, created_at INTEGER NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,app_id,id), UNIQUE(owner_id,app_id,request_key), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,id,request_key,created_at,data) AS BLOB)))) STRICT;
CREATE TABLE automation_transitions (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, job_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=0), now INTEGER NOT NULL, kind TEXT NOT NULL, authority_json TEXT CHECK(authority_json IS NULL OR json_valid(authority_json)), lease_json TEXT CHECK(lease_json IS NULL OR json_valid(lease_json)), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), deployment_id TEXT GENERATED ALWAYS AS (json_extract(data,'$.job.deploymentId')) STORED, PRIMARY KEY(owner_id,app_id,job_id,version), FOREIGN KEY(owner_id,app_id,job_id) REFERENCES automation_jobs(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id,deployment_id) REFERENCES ota_deployments(owner_id,app_id,id) DEFERRABLE INITIALLY DEFERRED, CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,job_id,version,now,kind,authority_json,lease_json,data) AS BLOB)))) STRICT;
CREATE TABLE automation_guards (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, id TEXT NOT NULL, job_id TEXT NOT NULL, now INTEGER NOT NULL, authority_json TEXT NOT NULL CHECK(json_valid(authority_json)), lease_json TEXT NOT NULL CHECK(json_valid(lease_json)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id,job_id) REFERENCES automation_jobs(owner_id,app_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,id,job_id,now,authority_json,lease_json) AS BLOB)))) STRICT;
CREATE TABLE automation_asset_refs (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, job_id TEXT NOT NULL, attempt_id TEXT NOT NULL, asset_hash TEXT NOT NULL, stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,app_id,job_id,attempt_id,asset_hash), FOREIGN KEY(owner_id,app_id,job_id) REFERENCES automation_jobs(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id,asset_hash) REFERENCES ota_assets(owner_id,app_id,hash), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,job_id,attempt_id,asset_hash) AS BLOB)))) STRICT;
CREATE TABLE automation_policies (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,app_id,version), FOREIGN KEY(owner_id,app_id) REFERENCES applications(owner_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,version,data) AS BLOB)))) STRICT;
CREATE TABLE automation_publications (owner_id TEXT NOT NULL, app_id TEXT NOT NULL, job_id TEXT NOT NULL, attempt_id TEXT NOT NULL, deployment_id TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), stored_bytes INTEGER NOT NULL CHECK(stored_bytes BETWEEN 1 AND 524288), PRIMARY KEY(owner_id,app_id,job_id), UNIQUE(owner_id,app_id,deployment_id), FOREIGN KEY(owner_id,app_id,job_id) REFERENCES automation_jobs(owner_id,app_id,id), FOREIGN KEY(owner_id,app_id,deployment_id) REFERENCES ota_deployments(owner_id,app_id,id), CHECK(stored_bytes=length(CAST(json_array(owner_id,app_id,job_id,attempt_id,deployment_id,data) AS BLOB)))) STRICT;
DROP TRIGGER capacity_integrity;
CREATE TRIGGER capacity_integrity BEFORE UPDATE ON flora_capacity WHEN NEW.singleton<>1 OR NEW.snapshot_count<>(SELECT count(*) FROM inventory_snapshots) OR NEW.baseline_count<>(SELECT count(*) FROM baseline_imports) OR NEW.payload_bytes<>(SELECT coalesce(sum(stored_bytes),0) FROM inventory_snapshots)+(SELECT coalesce(sum(stored_bytes),0) FROM baseline_imports)+(SELECT coalesce(sum(stored_bytes),0) FROM source_head_observations)+(SELECT coalesce(sum(stored_bytes),0) FROM applications)+(SELECT coalesce(sum(stored_bytes),0) FROM application_settings)+(SELECT coalesce(sum(stored_bytes),0) FROM github_connections)+(SELECT coalesce(sum(stored_bytes),0) FROM github_detections)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_assets)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_asset_chunks)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_deployments)+(SELECT coalesce(sum(stored_bytes),0) FROM ota_deployment_assets)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_runners)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_jobs)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_transitions)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_guards)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_asset_refs)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_policies)+(SELECT coalesce(sum(stored_bytes),0) FROM automation_publications) BEGIN SELECT RAISE(ABORT,'invalid capacity accounting'); END;
CREATE TRIGGER automation_runners_capacity BEFORE INSERT ON automation_runners WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_runners_account AFTER INSERT ON automation_runners BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_runners_update BEFORE UPDATE ON automation_runners BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_runners_delete BEFORE DELETE ON automation_runners BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_runners_replace BEFORE INSERT ON automation_runners WHEN EXISTS(SELECT 1 FROM automation_runners WHERE owner_id=NEW.owner_id AND id=NEW.id AND version=NEW.version) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_jobs_capacity BEFORE INSERT ON automation_jobs WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_jobs_account AFTER INSERT ON automation_jobs BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_jobs_update BEFORE UPDATE ON automation_jobs BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_jobs_delete BEFORE DELETE ON automation_jobs BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_jobs_replace BEFORE INSERT ON automation_jobs WHEN EXISTS(SELECT 1 FROM automation_jobs WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND (id=NEW.id OR request_key=NEW.request_key)) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_transitions_capacity BEFORE INSERT ON automation_transitions WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_transitions_account AFTER INSERT ON automation_transitions BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_transitions_update BEFORE UPDATE ON automation_transitions BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_transitions_delete BEFORE DELETE ON automation_transitions BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_transitions_replace BEFORE INSERT ON automation_transitions WHEN EXISTS(SELECT 1 FROM automation_transitions WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id AND version=NEW.version) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_guards_capacity BEFORE INSERT ON automation_guards WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_guards_account AFTER INSERT ON automation_guards BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_guards_update BEFORE UPDATE ON automation_guards BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_guards_delete BEFORE DELETE ON automation_guards BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_guards_replace BEFORE INSERT ON automation_guards WHEN EXISTS(SELECT 1 FROM automation_guards WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND id=NEW.id) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_asset_refs_capacity BEFORE INSERT ON automation_asset_refs WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_asset_refs_account AFTER INSERT ON automation_asset_refs BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_asset_refs_update BEFORE UPDATE ON automation_asset_refs BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_asset_refs_delete BEFORE DELETE ON automation_asset_refs BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_asset_refs_replace BEFORE INSERT ON automation_asset_refs WHEN EXISTS(SELECT 1 FROM automation_asset_refs WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id AND attempt_id=NEW.attempt_id AND asset_hash=NEW.asset_hash) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_policies_capacity BEFORE INSERT ON automation_policies WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_policies_account AFTER INSERT ON automation_policies BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_policies_update BEFORE UPDATE ON automation_policies BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_policies_delete BEFORE DELETE ON automation_policies BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_policies_replace BEFORE INSERT ON automation_policies WHEN EXISTS(SELECT 1 FROM automation_policies WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND version=NEW.version) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_publications_capacity BEFORE INSERT ON automation_publications WHEN NOT EXISTS(SELECT 1 FROM flora_capacity WHERE payload_bytes+NEW.stored_bytes<=134217728) BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_publications_account AFTER INSERT ON automation_publications BEGIN UPDATE flora_capacity SET payload_bytes=payload_bytes+NEW.stored_bytes WHERE singleton=1; END;
CREATE TRIGGER automation_publications_update BEFORE UPDATE ON automation_publications BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_publications_delete BEFORE DELETE ON automation_publications BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_publications_replace BEFORE INSERT ON automation_publications WHEN EXISTS(SELECT 1 FROM automation_publications WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id) BEGIN SELECT RAISE(ABORT,'immutable automation'); END;
CREATE TRIGGER automation_runner_version BEFORE INSERT ON automation_runners WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM automation_runners WHERE owner_id=NEW.owner_id AND id=NEW.id),1) OR json_extract(NEW.data,'$.id') IS NOT NEW.id BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_runner_limit BEFORE INSERT ON automation_runners WHEN NEW.version=1 AND (SELECT count(DISTINCT id) FROM automation_runners WHERE owner_id=NEW.owner_id)>=100 BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_job_limit BEFORE INSERT ON automation_jobs WHEN (SELECT count(*) FROM automation_jobs)>=1000 OR (SELECT count(*) FROM automation_transitions t WHERE t.version=(SELECT max(version) FROM automation_transitions WHERE owner_id=t.owner_id AND app_id=t.app_id AND job_id=t.job_id) AND json_extract(t.data,'$.job.state') IN ('queued','leased','cancel_requested'))>=100 OR (SELECT count(*) FROM automation_transitions t WHERE t.owner_id=NEW.owner_id AND t.app_id=NEW.app_id AND t.version=(SELECT max(version) FROM automation_transitions WHERE owner_id=t.owner_id AND app_id=t.app_id AND job_id=t.job_id) AND json_extract(t.data,'$.job.state') IN ('queued','leased','cancel_requested'))>=10 BEGIN SELECT RAISE(ABORT,'flora capacity exceeded'); END;
CREATE TRIGGER automation_transition_version BEFORE INSERT ON automation_transitions WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM automation_transitions WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id),0) OR json_extract(NEW.data,'$.job.id') IS NOT NEW.job_id OR json_extract(NEW.data,'$.job.appId') IS NOT NEW.app_id BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_transition_runner BEFORE INSERT ON automation_transitions WHEN NEW.authority_json IS NOT NULL AND NOT EXISTS(SELECT 1 FROM automation_runners r WHERE r.owner_id=NEW.owner_id AND r.id=json_extract(NEW.authority_json,'$.runnerId') AND r.version=(SELECT max(version) FROM automation_runners WHERE owner_id=r.owner_id AND id=r.id) AND json_extract(r.data,'$.credentialEpoch')=json_extract(NEW.authority_json,'$.credentialEpoch') AND json_extract(r.data,'$.tokenHash')=json_extract(NEW.authority_json,'$.tokenHash') AND json_extract(r.data,'$.revokedAt') IS NULL AND EXISTS(SELECT 1 FROM json_each(r.data,'$.appIds') WHERE value=NEW.app_id)) BEGIN SELECT RAISE(ABORT,'runner authority'); END;
CREATE TRIGGER automation_transition_lease BEFORE INSERT ON automation_transitions WHEN NEW.lease_json IS NOT NULL AND NOT EXISTS(SELECT 1 FROM automation_transitions t WHERE t.owner_id=NEW.owner_id AND t.app_id=NEW.app_id AND t.job_id=NEW.job_id AND t.version=(SELECT max(version) FROM automation_transitions WHERE owner_id=t.owner_id AND app_id=t.app_id AND job_id=t.job_id) AND json_extract(t.data,'$.job.state') IN ('leased','cancel_requested') AND json_extract(t.data,'$.job.lease.attemptId')=json_extract(NEW.lease_json,'$.attemptId') AND json_extract(t.data,'$.job.lease.fence')=json_extract(NEW.lease_json,'$.fence') AND json_extract(t.data,'$.job.lease.runnerId')=json_extract(NEW.authority_json,'$.runnerId') AND json_extract(t.data,'$.job.lease.credentialEpoch')=json_extract(NEW.authority_json,'$.credentialEpoch') AND json_extract(t.data,'$.job.lease.expiresAt')>NEW.now AND json_extract(t.data,'$.attempt.claimedAt')+1200000>NEW.now) BEGIN SELECT RAISE(ABORT,'lease fence'); END;
CREATE TRIGGER automation_guard_runner BEFORE INSERT ON automation_guards WHEN NOT EXISTS(SELECT 1 FROM automation_runners r WHERE r.owner_id=NEW.owner_id AND r.id=json_extract(NEW.authority_json,'$.runnerId') AND r.version=(SELECT max(version) FROM automation_runners WHERE owner_id=r.owner_id AND id=r.id) AND json_extract(r.data,'$.credentialEpoch')=json_extract(NEW.authority_json,'$.credentialEpoch') AND json_extract(r.data,'$.tokenHash')=json_extract(NEW.authority_json,'$.tokenHash') AND json_extract(r.data,'$.revokedAt') IS NULL AND EXISTS(SELECT 1 FROM json_each(r.data,'$.appIds') WHERE value=NEW.app_id)) BEGIN SELECT RAISE(ABORT,'runner authority'); END;
CREATE TRIGGER automation_guard_lease BEFORE INSERT ON automation_guards WHEN NOT EXISTS(SELECT 1 FROM automation_transitions t WHERE t.owner_id=NEW.owner_id AND t.app_id=NEW.app_id AND t.job_id=NEW.job_id AND t.version=(SELECT max(version) FROM automation_transitions WHERE owner_id=t.owner_id AND app_id=t.app_id AND job_id=t.job_id) AND json_extract(t.data,'$.job.state') IN ('leased') AND json_extract(t.data,'$.job.lease.attemptId')=json_extract(NEW.lease_json,'$.attemptId') AND json_extract(t.data,'$.job.lease.fence')=json_extract(NEW.lease_json,'$.fence') AND json_extract(t.data,'$.job.lease.runnerId')=json_extract(NEW.authority_json,'$.runnerId') AND json_extract(t.data,'$.job.lease.credentialEpoch')=json_extract(NEW.authority_json,'$.credentialEpoch') AND json_extract(t.data,'$.job.lease.expiresAt')>NEW.now AND json_extract(t.data,'$.attempt.claimedAt')+1200000>NEW.now) BEGIN SELECT RAISE(ABORT,'lease fence'); END;
CREATE INDEX automation_job_pages ON automation_jobs(owner_id,app_id,created_at DESC,id DESC);
CREATE TRIGGER automation_pinned_job BEFORE INSERT ON automation_transitions WHEN NOT EXISTS(SELECT 1 FROM automation_jobs j WHERE j.owner_id=NEW.owner_id AND j.app_id=NEW.app_id AND j.id=NEW.job_id AND json_remove(j.data,'$.state','$.updatedAt','$.attemptCount','$.lease','$.code','$.deploymentId','$.receipt')=json_remove(json_extract(NEW.data,'$.job'),'$.state','$.updatedAt','$.attemptCount','$.lease','$.code','$.deploymentId','$.receipt')) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_claim_state BEFORE INSERT ON automation_transitions WHEN NEW.kind='claimed' AND NOT EXISTS(SELECT 1 FROM automation_transitions t WHERE t.owner_id=NEW.owner_id AND t.app_id=NEW.app_id AND t.job_id=NEW.job_id AND t.version=NEW.version-1 AND json_extract(t.data,'$.job.state')='queued' AND json_extract(t.data,'$.job.attemptCount')<3 AND json_extract(NEW.data,'$.job.attemptCount')=json_extract(t.data,'$.job.attemptCount')+1 AND json_extract(NEW.data,'$.job.lease.fence')=json_extract(NEW.data,'$.job.attemptCount') AND json_extract(NEW.data,'$.job.lease.runnerId')=json_extract(NEW.authority_json,'$.runnerId')) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_upload_binding BEFORE INSERT ON automation_asset_refs WHEN NOT EXISTS(SELECT 1 FROM automation_guards WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id AND json_extract(lease_json,'$.attemptId')=NEW.attempt_id) BEGIN SELECT RAISE(ABORT,'lease fence'); END;
CREATE TRIGGER automation_policy_version BEFORE INSERT ON automation_policies WHEN NEW.version<>coalesce((SELECT max(version)+1 FROM automation_policies WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id),1) OR json_extract(NEW.data,'$.version') IS NOT NEW.version OR json_extract(NEW.data,'$.appId') IS NOT NEW.app_id BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_latest_intent BEFORE INSERT ON automation_transitions WHEN NEW.kind='succeeded' AND EXISTS(SELECT 1 FROM automation_jobs j JOIN automation_jobs newer ON newer.owner_id=j.owner_id AND newer.app_id=j.app_id WHERE j.owner_id=NEW.owner_id AND j.app_id=NEW.app_id AND j.id=NEW.job_id AND json_extract(newer.data,'$.channel')=json_extract(j.data,'$.channel') AND json_extract(newer.data,'$.runtimeVersion')=json_extract(j.data,'$.runtimeVersion') AND json_extract(newer.data,'$.platform')=json_extract(j.data,'$.platform') AND (newer.created_at>j.created_at OR (newer.created_at=j.created_at AND newer.rowid>j.rowid))) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_job_binding BEFORE INSERT ON automation_jobs WHEN json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.appId') IS NOT NEW.app_id OR json_extract(NEW.data,'$.requestKey') IS NOT NEW.request_key OR json_extract(NEW.data,'$.createdAt') IS NOT NEW.created_at OR json_extract(NEW.data,'$.state') IS NOT 'queued' OR NOT EXISTS(SELECT 1 FROM github_detections d JOIN github_connections c ON c.owner_id=d.owner_id AND c.app_id=d.app_id WHERE d.owner_id=NEW.owner_id AND d.app_id=NEW.app_id AND d.id=json_extract(NEW.data,'$.detectionId') AND json(d.data)=json_extract(NEW.data,'$.detection') AND c.version=(SELECT max(version) FROM github_connections WHERE owner_id=c.owner_id AND app_id=c.app_id) AND json(c.data)=json_extract(NEW.data,'$.connection')) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_event_binding BEFORE INSERT ON automation_transitions WHEN json_extract(NEW.data,'$.event.kind') IS NOT NEW.kind OR json_extract(NEW.data,'$.event.jobId') IS NOT NEW.job_id OR json_extract(NEW.data,'$.event.createdAt') IS NOT NEW.now OR json_extract(NEW.data,'$.job.updatedAt') IS NOT NEW.now OR json_extract(NEW.data,'$.event.sequence') IS NOT coalesce((SELECT json_extract(data,'$.event.sequence')+1 FROM automation_transitions WHERE owner_id=NEW.owner_id AND app_id=NEW.app_id AND job_id=NEW.job_id ORDER BY version DESC LIMIT 1),1) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_success_binding BEFORE INSERT ON automation_transitions WHEN NEW.kind='succeeded' AND (NEW.authority_json IS NULL OR NEW.lease_json IS NULL OR json_extract(NEW.data,'$.job.state') IS NOT 'succeeded' OR NEW.deployment_id IS NULL OR json_extract(NEW.data,'$.job.receipt.jobId') IS NOT NEW.job_id OR json_extract(NEW.data,'$.job.receipt.attemptId') IS NOT json_extract(NEW.lease_json,'$.attemptId')) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_publication_binding BEFORE INSERT ON automation_publications WHEN NOT EXISTS(SELECT 1 FROM automation_jobs j JOIN ota_deployments d ON d.owner_id=j.owner_id AND d.app_id=j.app_id JOIN automation_transitions t ON t.owner_id=j.owner_id AND t.app_id=j.app_id AND t.job_id=j.id WHERE j.owner_id=NEW.owner_id AND j.app_id=NEW.app_id AND j.id=NEW.job_id AND d.id=NEW.deployment_id AND d.request_key=j.id AND d.channel=json_extract(j.data,'$.channel') AND d.runtime_version=json_extract(j.data,'$.runtimeVersion') AND d.platform=json_extract(j.data,'$.platform') AND json_extract(d.data,'$.commitSha')=json_extract(j.data,'$.commitSha') AND json_extract(d.data,'$.detectionId')=json_extract(j.data,'$.detectionId') AND t.version=(SELECT max(version) FROM automation_transitions WHERE owner_id=j.owner_id AND app_id=j.app_id AND job_id=j.id) AND json_extract(t.data,'$.job.state')='succeeded' AND json_extract(t.data,'$.job.deploymentId')=NEW.deployment_id AND json_extract(t.data,'$.job.receipt')=json(NEW.data) AND json_extract(NEW.data,'$.attemptId')=NEW.attempt_id) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
CREATE TRIGGER automation_runner_binding BEFORE INSERT ON automation_runners WHEN json_extract(NEW.data,'$.credentialEpoch') IS NOT NEW.version OR (NEW.version>1 AND NOT EXISTS(SELECT 1 FROM automation_runners r WHERE r.owner_id=NEW.owner_id AND r.id=NEW.id AND r.version=NEW.version-1 AND json_remove(r.data,'$.credentialEpoch','$.revokedAt')=json_remove(NEW.data,'$.credentialEpoch','$.revokedAt'))) BEGIN SELECT RAISE(ABORT,'runner authority'); END;
CREATE TRIGGER automation_recipe_source BEFORE INSERT ON automation_jobs WHEN NOT EXISTS(SELECT 1 FROM github_detections d WHERE d.owner_id=NEW.owner_id AND d.app_id=NEW.app_id AND d.id=json_extract(NEW.data,'$.detectionId') AND json_extract(d.data,'$.automationConfig')=json_extract(NEW.data,'$.config') AND json_extract(d.data,'$.runtimeVersion')=json_extract(NEW.data,'$.runtimeVersion') AND EXISTS(SELECT 1 FROM json_each(d.data,'$.platforms') WHERE value=json_extract(NEW.data,'$.platform'))) BEGIN SELECT RAISE(ABORT,'automation conflict'); END;
